svg.script:

document.addEventListener("DOMContentLoaded", function() {
  // Находим САМУЮ ПЕРВУЮ группу в файле (ваше колесо)
  var firstGroup = document.querySelector("svg > g");
  if (firstGroup) {
    // Принудительно ставим ей нужный ID, чтобы скрипт её видел
    firstGroup.setAttribute("id", "wheel-group");
  }
});

function targetMonth(angle, url) {
  var wheel = document.getElementById('wheel-group');
  if (wheel) {
    var rotation = 90 - angle;
    wheel.style.transition = "transform 1.5s ease-out";
    wheel.style.transformOrigin = "50% 50%"; 
    wheel.style.transform = "rotate(" + rotation + "deg)";
    setTimeout(function() { window.open(url, '_blank'); }, 1500);
  }
}
